layers.vertex:
attribute vec3 aO, aE, aF; attribute float aT; uniform float uTime; varying vec3 vN, vV; varying float vHeat;
    void main(){
      float u = uTime - aT - 0.26;
      vec3 D = aE - aO; float L = length(D); vec3 dir = D/L;
      float hit = aF.x, i = aF.y, SP = aF.z;
      float tR = .1 + L/14.0, kc = u - tR;                   // time since contact (or since reaching max range)
      float p = clamp(u/tR, 0., 1.), ext = L*p*p*(1.6 - .6*p);          // slow out of the hand, fast on arrival
      if (hit < .5 && kc > 0.) ext = L - 24.0*kc;          // miss: reel back in
      float s = ext - i*SP;                                             // this link's distance from the hand
      float life = hit > .5 ? tR + 0.77 : tR + L/24.0;
      if (u < 0. || u > life || s < 0.){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 up = vec3(0., 1., 0.), a = normalize(cross(dir, up)), b = cross(a, dir);
      float amp = 0.;
      if (kc < 0.) amp = .06*sin(3.14159*clamp(s/max(ext, .01), 0., 1.))*sin(s*5. - u*38.);          // light whip while travelling
      else if (hit > .5) amp = .035*exp(-kc*22.)*sin(kc*70.)*sin(3.14159*clamp(s/L, 0., 1.));      // snaps taut: one shudder, then rigid
      float heat = .22 + .9*exp(-(ext - s)*4.)*(kc < 0. ? 1. : exp(-kc*8.));                       // leading links run hot
      float sc = 1.;
      if (hit > .5 && kc >= 0.){
        heat += .5*exp(-kc*9.);                                                                   // contact flash along the chain
        float w = L - 20.*kc; heat += 1.1*exp(-pow((s - w)/.3, 2.))*step(-.3, w);               // recoil wave: target → hand
        float wipe = (kc - 0.45)/0.32*(L + .6) - .3;                 // dissolve from the hand; tip last
        sc = smoothstep(wipe - .05, wipe + .45, s);
        heat += 1.2*exp(-pow((s - wipe - .2)/.25, 2.))*step(0.45, kc);
      }
      if (hit < .5 && kc >= 0.) heat *= exp(-kc*3.);
      if (sc < .01){ gl_Position = vec4(2.,2.,2.,1.); return; }
      bool odd = mod(i, 2.) > .5;
      vec3 ax = odd ? a : b, az = odd ? b : a;                          // links alternate 90° around the chain axis
      float big = i < .5 ? 1.25 : 1.;                                   // the leading link is a little heavier
      vec3 wp = (dir*position.x*.12 + ax*position.y*.07 + az*position.z*.07)*sc*big;
      vN = normalize(dir*normal.x/.12 + ax*normal.y/.07 + az*normal.z/.07);
      vec3 P = aO + dir*s + (a*.5 + b)*amp + wp;
      vV = normalize(cameraPosition - P); vHeat = heat;
      gl_Position = projectionMatrix*viewMatrix*vec4(P, 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange, uMoon; varying vec3 vN, vV; varying float vHeat;
    void main(){
      vec3 n = normalize(vN), v = normalize(vV);
      float rim = pow(1. - abs(dot(n, v)), 2.4);                                // glow lives on the contour: reads as light, not metal
      vec3 col = mix(uOrange, uGold, .45 + .45*rim);
      vec3 c = col*(.025 + .36*rim)*(.45 + vHeat) + vec3(1., .95, .86)*rim*max(vHeat - .7, 0.)*.2;
      gl_FragColor = vec4(c, 1.);
    }

layers.vertex:
attribute vec3 aO, aE; attribute float aF, aT; uniform float uTime; varying float vS, vY, vX, vL, vKc, vHit, vU;
    void main(){
      float u = uTime - aT - 0.26;
      vec3 D = aE - aO; float L = length(D); vec3 dir = D/L;
      float tR = .1 + L/14.0, kc = u - tR;
      float p = clamp(u/tR, 0., 1.), ext = L*p*p*(1.6 - .6*p);
      if (aF < .5 && kc > 0.) ext = L - 24.0*kc;
      float life = aF > .5 ? tR + 0.77 : tR + L/24.0;
      if (u < 0. || u > life || ext <= 0.){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float x = position.x*.5 + .5, s = x*ext;
      vec3 P = aO + dir*s;
      vec3 side = normalize(cross(dir, P - cameraPosition));
      float W = .2;
      vS = s; vX = x; vY = position.y; vL = L; vKc = kc; vHit = aF; vU = u;
      gl_Position = projectionMatrix*viewMatrix*vec4(P + side*position.y*W, 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying float vS, vY, vX, vL, vKc, vHit, vU; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      float band = exp(-vY*vY*5.), core = lcore(vY, .12);
      float ends = pow(sin(3.14159*clamp(vX, 0., 1.)), .6);                 // soft at the hand and at the tip
      float heat = .5 + .6*smoothstep(.6, 1., vX)*(vKc < 0. ? 1. : exp(-vKc*8.));
      float m = 1.;
      if (vHit > .5 && vKc >= 0.){
        heat += .6*exp(-vKc*9.);
        float w = vL - 20.*vKc; heat += 1.2*exp(-pow((vS - w)/.35, 2.))*step(-.3, w);
        float wipe = (vKc - 0.45)/0.32*(vL + .6) - .3;
        m = smoothstep(wipe - .05, wipe + .5, vS);
      }
      if (vHit < .5 && vKc >= 0.) heat *= exp(-vKc*3.);
      vec3 col = mix(uOrange, uGold, .5);
      vec3 outc = (col*band*.07 + mix(uGold, vec3(1., .96, .88), .5)*core*.04)*heat*ends*m;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }
